/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { CoordSys3D, Matrix, Vector, VectorMul, VectorPoint, rational } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.vector.point", () => {
  it("p2.express_coordinates(N)", () => {
    const v1 = VectorPoint('p2', VectorMul(rational(5), at(CoordSys3D('N', { vectorNames: ['i', 'j', 'k'], variableNames: ['x', 'y', 'z'], rotationMatrix: Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]) }).baseVectors(), 1)), VectorPoint('p1', VectorMul(rational(10), at(CoordSys3D('N', { vectorNames: ['i', 'j', 'k'], variableNames: ['x', 'y', 'z'], rotationMatrix: Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]) }).baseVectors(), 0)), VectorPoint('N.origin', Vector.zero))).expressCoordinates(CoordSys3D('N', { vectorNames: ['i', 'j', 'k'], variableNames: ['x', 'y', 'z'], rotationMatrix: Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]) }));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(10, 5, 0)')).toBe(true);
  });
  it("p1.position_wrt(N.origin)", () => {
    expect(sympyStr(VectorPoint('p1', VectorMul(rational(10), at(CoordSys3D('N', { vectorNames: ['i', 'j', 'k'], variableNames: ['x', 'y', 'z'], rotationMatrix: Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]) }).baseVectors(), 0)), VectorPoint('N.origin', Vector.zero)).positionWrt(VectorPoint('N.origin', Vector.zero)))).toBe('10*N.i');
  });
  it("N.origin.position_wrt(p1)", () => {
    expect(sympyStr(VectorPoint('N.origin', Vector.zero).positionWrt(VectorPoint('p1', VectorMul(rational(10), at(CoordSys3D('N', { vectorNames: ['i', 'j', 'k'], variableNames: ['x', 'y', 'z'], rotationMatrix: Matrix.of([[rational(1), rational(0), rational(0)], [rational(0), rational(1), rational(0)], [rational(0), rational(0), rational(1)]]) }).baseVectors(), 0)), VectorPoint('N.origin', Vector.zero))))).toBe('(-10)*N.i');
  });
});
